-- Énergie : stock de base ×2, recharge ÷3. Le plein à la montée de niveau
-- reste. Le stock s'agrandit surtout par la compétence Endurance (PC_VAULT,
-- +160 au rang max, soit +133 %) ; Récupération (PC_REGEN) garde son poids
-- relatif (-23 % de délai au rang max).
--
-- Migration de DONNÉES : le bootstrap de `GlobalConfig` est create-only et le
-- déploiement ne reseede jamais. Les gardes sur les anciennes valeurs la
-- rendent idempotente et laissent survivre un ajustement manuel.
UPDATE "GlobalConfig" SET value = '120' WHERE key = 'combat.pointsMax' AND value = '60';
UPDATE "GlobalConfig" SET value = '300' WHERE key = 'combat.regenSeconds' AND value = '900';

UPDATE "SkillNodeLevel" l SET effect = v.new
FROM "SkillNode" n,
  (VALUES (1, 5, 30), (2, 10, 60), (3, 15, 90), (4, 20, 120), (5, 25, 160)) AS v(level, old, new)
WHERE l."nodeId" = n.id AND n."effectType" = 'PC_VAULT'::"SkillEffectType"
  AND l.level = v.level AND l.effect = v.old;

UPDATE "SkillNodeLevel" l SET effect = v.new
FROM "SkillNode" n,
  (VALUES (1, 60, 20), (2, 120, 40), (3, 180, 60), (4, 210, 70)) AS v(level, old, new)
WHERE l."nodeId" = n.id AND n."effectType" = 'PC_REGEN'::"SkillEffectType"
  AND l.level = v.level AND l.effect = v.old;

-- Avantage élémentaire : ×1,30 -> ×1,25 de dégâts, et +15 points de taux
-- critique (`combat.elementAdvantageCritBonus`, créé par le bootstrap).
UPDATE "GlobalConfig" SET value = '1.25' WHERE key = 'combat.elementAdvantageMult' AND value = '1.3';

-- Bottes : stat principale taux critique divisée par deux (MAIN_STAT_SCALE).
-- Catalogue seulement : les pièces des joueurs pointent sur ces lignes.
UPDATE "Equipment" e
SET "bonuses" = jsonb_build_object('critRatePct', v.nouveau)
FROM (VALUES
  ('COMMON', 6, 3),
  ('UNCOMMON', 9, 5),
  ('RARE', 14, 7),
  ('EPIC', 21, 11),
  ('LEGENDARY', 32, 16)
) AS v(rarity, ancien, nouveau)
WHERE e."mainStat" = 'critRatePct'
  AND e."rarity"::text = v.rarity
  AND (e."bonuses"->>'critRatePct')::numeric = v.ancien;

