-- Apogée de Combat (DROP_BONUS) : le bonus relève la rareté des pièces au lieu
-- de leur nombre. Seul le texte change, les valeurs par rang restent.
UPDATE "SkillNode"
SET "descriptionFr" = 'Relève la rareté des pièces d''équipement gagnées en combat',
    "descriptionEn" = 'Raises the rarity of equipment won in battle'
WHERE "effectType" = 'DROP_BONUS'
  AND "descriptionFr" = 'Bonus de chance d''équipement en combat';
